'use client';
import {useEffect,useState,useMemo} from 'react';
import {useScreen,navigate,back} from '../lib/use-screen';
import {Users,Search,ArrowLeft,FileText,Download,Upload,Check,AlertCircle,RefreshCw,UserRound,History,ShieldCheck} from 'lucide-react';
import {LineChart,Line,BarChart,Bar,XAxis,YAxis,CartesianGrid,Tooltip,Legend,ResponsiveContainer} from 'recharts';
import type {AgentSource,AgentRecord} from '../lib/agents';
import {M3eTable} from './family-focus';
import {m3eKey,m3eLabel} from '../lib/agent-m3e';
import HourlySummary from './hourly-summary';
import AgentRemuneration from './agent-remuneration';
import {ANNUAL_HOURS,hourlyRates} from '../lib/agent-hourly';
import FamilyFocus from './family-focus';
import {normalName,careerSeniority} from '../lib/agents';
import {importFields,detectMapping,mapAgentRows,readAgentWorkbook} from '../lib/agents-import';
const fmt=(v:any)=>typeof v==='number'?new Intl.NumberFormat('fr-FR',{maximumFractionDigits:2}).format(v):v||'Non renseigné';
const date=(v?:string)=>v?new Intl.DateTimeFormat('fr-FR',{dateStyle:'medium',timeZone:'UTC'}).format(new Date(v+'T12:00:00Z')):'Non renseignée';
const decisionNote=(value:string)=>{try{const parsed=JSON.parse(value);return parsed.presence?parsed.note:value;}catch{return value;}};
const colleges:Record<string,string>={cadres:'Cadres',maitrise:'Maîtrise',execution:'Exécution'};
async function api(url:string,init?:RequestInit){const res=await fetch(url,init);const data:any=await res.json();if(!res.ok)throw Error(data.error||'Opération impossible.');return data;}
function csv(name:string,rows:unknown[][]){const a=document.createElement('a');const url=URL.createObjectURL(new Blob(['\ufeff'+rows.map(r=>r.map(v=>'"'+String(v??'').replaceAll('"','""')+'"').join(';')).join('\r\n')],{type:'text/csv;charset=utf-8'}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),500);}
const tabs=[['list','Agents'],['movements','Mouvements'],['identity','Rapprochements'],['executives','Cadres dirigeants']];
export default function Agents({isAdmin=false,refreshRevision=0,importedSource="",onImported,forcedView}:{isAdmin?:boolean;refreshRevision?:number;importedSource?:string;onImported?:(id:string)=>void;forcedView?:'families'|'analysis'|'payroll'|'hourly'}){const [meta,setMeta]=useState<any>(null);const [source,setSource]=useScreen('agentSource','');const [storedView,setView]=useScreen('agentView','list');const view=forcedView||(['analysis','families','payroll','imports'].includes(storedView)?'list':storedView);const [result,setResult]=useState<any>(null);const [profile,setProfile]=useState<any>(null);const [q,setQ]=useState('');const [agency,setAgency]=useState('');const [college,setCollege]=useState('');const [m3e,setM3e]=useState('');const [gf,setGF]=useState('');const [nr,setNR]=useState('');const [years,setYears]=useState('');const [sort,setSort]=useState('name');const [archive,setArchive]=useState(false);const [absenceFilter,setAbsenceFilter]=useState<'pending'|'confirmed'|'executives'|'all'>('pending');const [executiveName,setExecutiveName]=useState('');const [executiveOrigin,setExecutiveOrigin]=useState('');const [executiveDate,setExecutiveDate]=useState('');const [executiveNote,setExecutiveNote]=useState('');const [dismissed,setDismissed]=useState(false);const [chosenPending,setChosenPending]=useState<string[]>([]);const [offset,setOffset]=useState(0);const [previous,setPrevious]=useState('');const [residence,setResidence]=useState('agency');const [gridRef,setGridRef]=useState('');const [bonusRef,setBonusRef]=useState('');const [notice,setNotice]=useState('');const [busy,setBusy]=useState(false);const [revision,setRevision]=useState(0);const [review,setReview]=useState<any>(null);
const [profileId,setProfileId]=useScreen('agentProfile','');
const [reviewId,setReviewId]=useScreen('agentReview','');
useEffect(()=>{if(!isAdmin&&['imports','identity'].includes(view))navigate({agentView:'list',agentReview:''});},[isAdmin,view]);
useEffect(()=>{setProfile(null);if(!profileId)return;const c=new AbortController();setBusy(true);api('/api/agents/'+encodeURIComponent(profileId),{signal:c.signal}).then(setProfile).catch(e=>{if(e.name!=='AbortError')setNotice(e.message);}).finally(()=>{if(!c.signal.aborted)setBusy(false);});return()=>c.abort();},[profileId,refreshRevision]);
useEffect(()=>{setReview(null);if(!isAdmin||!reviewId)return;const c=new AbortController();api('/api/agents/import/'+encodeURIComponent(reviewId),{signal:c.signal}).then(setReview).catch(e=>{if(e.name!=='AbortError')setNotice(e.message);});return()=>c.abort();},[reviewId,isAdmin]);
const reload=async()=>{const m=await api('/api/agents?view=meta');setMeta(m);const available=m.sources.filter((s:AgentSource)=>s.status!=='review');if(!available.some((s:AgentSource)=>s.id===source)){const primary=available.filter((s:AgentSource)=>s.primary);setSource((primary.at(-1)||available.filter((s:AgentSource)=>s.status==='validated').at(-1))?.id||'');}};
useEffect(()=>{reload().then(()=>{if(importedSource){setSource(importedSource);setAgency('');setCollege('');setGF('');setNR('');setM3e('');setPrevious('');}setRevision(r=>r+1);}).catch(e=>setNotice(e.message));},[refreshRevision,importedSource]);
// On opening Mouvements, always begin with the two most recent distinct yearly snapshots.
// When two 2024 versions exist, favor "onglets mis en forme".
useEffect(()=>{
 if(view!=='movements'||!meta?.sources?.length)return;
 const available:AgentSource[]=meta.sources.filter((x:AgentSource)=>x.status!=='review'&&x.date);
 const dates=[...new Set(available.map(x=>x.date))].sort((a,b)=>b.localeCompare(a));
 if(dates.length<2)return;
 const latest=available.filter(x=>x.date===dates[0]).sort((a,b)=>Number(!!b.primary)-Number(!!a.primary))[0];
 const older=available.filter(x=>x.date===dates[1]).sort((a,b)=>{
  const rank=(x:AgentSource)=>/onglets? mis en forme/i.test(x.name+' '+x.label)?2:Number(!!x.primary);
  return rank(b)-rank(a);
 })[0];
 if(latest)setSource(latest.id);
 if(older)setPrevious(older.id);
},[view,!!meta,refreshRevision,importedSource]);
useEffect(()=>{setOffset(0);},[source,q,agency,college,gf,nr,m3e,years,archive,view,dismissed]);
// An approved reference can supersede a previously selected grid or annual bonus schedule.
// Clear pinned references on import so the API chooses its newest validated ones.
useEffect(()=>{setGridRef('');setBonusRef('');},[refreshRevision]);
useEffect(()=>{if(!source||view==='imports')return;const c=new AbortController();setBusy(true);const p=new URLSearchParams({source,view:view==='hourly'?'payroll':view,q,agency,college,gf,nr,m3e,years,sort,archive:archive?'1':'0',dismissed:dismissed?'1':'0',offset:String(offset),previous,residence,grid:gridRef,bonus:bonusRef});api('/api/agents?'+p,{signal:c.signal}).then(d=>{if(c.signal.aborted)return;setResult(d);if((view==='payroll'||view==='hourly')&&d.residence&&d.residence!==residence)setResidence(d.residence);}).catch(e=>{if(e.name!=='AbortError')setNotice(e.message);}).finally(()=>{if(!c.signal.aborted)setBusy(false);});return()=>c.abort();},[source,view,q,agency,college,gf,nr,m3e,years,sort,archive,dismissed,offset,previous,residence,gridRef,bonusRef,revision]);
const open=(id:string)=>setProfileId(id);
// Update the visible row and counters as soon as the server confirms the write.
// A subsequent fetch still validates the canonical data from the database.
const applySavedDecision=(body:any)=>{
 const saved={id:'local-'+crypto.randomUUID(),agent:body.agent,kind:body.kind,source:body.source,target:body.target||null,note:body.note||'',created:new Date().toISOString()};
 setResult((old:any)=>{
  if(!old)return old;
  if(view==='movements')return {...old,decisions:[...(old.decisions||[]),saved]};
  if(view==='identity'&&['dismiss','restore'].includes(body.kind)){
   const currentlyShowingDismissed=dismissed;
   const shouldRemove=(body.kind==='dismiss'&&!currentlyShowingDismissed)||(body.kind==='restore'&&currentlyShowingDismissed);
   if(shouldRemove)return {...old,records:(old.records||[]).filter((r:any)=>!(r.agentId===body.agent&&r.source===body.source)),total:Math.max(0,(old.total||0)-1)};
  }
  if(view==='executives'&&body.kind==='executive_remove')return {...old,records:(old.records||[]).filter((r:any)=>r.agentId!==body.agent),total:Math.max(0,(old.total||0)-1)};
  if(view==='executives'&&body.kind==='executive_update')return {...old,records:(old.records||[]).map((r:any)=>r.agentId===body.agent?{...r,name:body.name,origin:body.origin,startDate:body.startDate,exitDate:body.exitDate,note:body.note}:r).sort((a:any,b:any)=>a.name.localeCompare(b.name,'fr'))};
  if(view==='executives'&&body.kind==='executive_manual')return {...old,records:[...(old.records||[]),{agentId:body.agent,source:body.source,name:body.name,origin:body.origin,startDate:body.startDate,exitDate:'',note:body.note,manual:true}].sort((a:any,b:any)=>a.name.localeCompare(b.name,'fr')),total:(old.total||0)+1};
  return old;
 });
};
const decide=async(body:any)=>{
 setBusy(true);
 try{
  await api('/api/agents/decision',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});
  applySavedDecision(body);
  setNotice(body.kind==='return'?'Présence confirmée. Les effectifs et analyses sont recalculés ; l’historique est conservé.':body.kind==='executive'||body.kind==='executive_manual'?'Cadre dirigeant enregistré à part. Aucun ajout aux effectifs.':'Décision enregistrée. L’historique est conservé.');
  setRevision(r=>r+1);
  if(profile)setProfile(await api('/api/agents/'+encodeURIComponent(profile.id)));
  return true;
 }catch(e){setNotice((e as Error).message);return false;}
 finally{setBusy(false);}
};
const archivePending=async(rows:any[],kind:'dismiss'|'restore')=>{
 if(!rows.length||!window.confirm(kind==='dismiss'?'Retirer '+rows.length+' fiche(s) des rapprochements ? Les données historiques seront conservées.':'Restaurer '+rows.length+' fiche(s) dans les rapprochements ?'))return;
 setBusy(true);
 let completed=0;
 try{
  for(const r of rows){
   await api('/api/agents/decision',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({kind,agent:r.agentId,source:r.source})});
   applySavedDecision({kind,agent:r.agentId,source:r.source});
   completed++;
  }
  setChosenPending([]);
  setNotice(kind==='dismiss'?'Fiches placées dans la corbeille. Historique conservé.':'Fiches restaurées dans les rapprochements.');
 }catch(e){setNotice(completed+' fiche(s) traitée(s). '+(e as Error).message);}
 finally{if(completed)setRevision(v=>v+1);setBusy(false);}
};
const loadReview=async(id:string)=>navigate({agentView:'imports',agentReview:id});
if(!meta)return <section className="panel"><ShieldCheck/><h2>Chargement de l’espace individuel</h2><p>{notice||'Connexion requise pour consulter Socioscope ULM.'}</p></section>;
const sources:AgentSource[]=meta.sources;const active=sources.find(s=>s.id===source);const list=result?.records||[];
// The latest administrator decision for each agent and reference source prevails.
const movementDecisions=new Map<string,any>();
for(const d of result?.decisions||[])if(d.source===source&&['departure','return','absence','executive','executive_remove'].includes(d.kind))movementDecisions.set(d.agent,d);
const absences=result?.absent||[];
const pendingAbsences=absences.filter((r:any)=>!['departure','return','executive'].includes(movementDecisions.get(r.agentId)?.kind)&&!r.manualPresence);
const confirmedAbsences=absences.filter((r:any)=>movementDecisions.get(r.agentId)?.kind==='departure');const executiveAbsences=absences.filter((r:any)=>movementDecisions.get(r.agentId)?.kind==='executive');
const displayedAbsences=absenceFilter==='pending'?pendingAbsences:absenceFilter==='confirmed'?confirmedAbsences:absenceFilter==='executives'?executiveAbsences:absences;
return <div className="agents-workspace"><div className="agent-private"><ShieldCheck size={18}/><span>{isAdmin?'Administration · données nominatives':'Consultation seule · données nominatives'} · anciennetés à la date du fichier</span></div>{notice&&<div className="notice" role="status"><AlertCircle size={17}/><span>{notice}</span><button className="text-btn" onClick={()=>setNotice('')}>Fermer</button></div>}{busy&&<div className="notice"><RefreshCw className="spin" size={16}/>Chargement…</div>}
{profile?<AgentProfile isAdmin={isAdmin} gridRef={gridRef} bonusRef={bonusRef} residence={residence} profile={profile} preferred={source} sources={sources} onBack={back} onDecision={decide}/>:<>{!forcedView&&<div className="agent-tabs segmented">{tabs.filter(([id])=>isAdmin||!['imports','identity'].includes(id)).map(([id,label])=><button key={id} className={view===id?'selected':''} onClick={()=>{navigate({agentView:id,agentReview:'',agentProfile:''});setResult(null);setReview(null);setQ('');setAgency('');setCollege('');setGF('');setNR('');setYears('');}}>{label}{id==='identity'&&meta.pending>0&&<span className="badge amber">{meta.pending}</span>}</button>)}</div>}
{view!=='imports'&&<div className="analysis-options"><label>Photographie de référence<select aria-label="Fichier individuel de référence" value={source} onChange={e=>{setSource(e.target.value);setAgency('');setCollege('');setGF('');setNR('');setM3e('');setPrevious('');}}>{sources.filter(s=>s.status!=='review').map(s=><option key={s.id} value={s.id}>{s.label}{!s.primary?' · version alternative / partielle':''}</option>)}</select></label><span className="filter-note">{active?.confidence} · {active?.agents} fiches dans la source</span></div>}
{['list','analysis','families'].includes(view)&&<div className="analysis-options"><label>Plage M3E<select value={m3e} onChange={e=>setM3e(e.target.value)}><option value="">Toutes les plages</option>{result?.plages?.map((p:any)=><option key={p.id} value={p.id}>{p.label}</option>)}</select></label><span className="filter-note">Plage du fichier · bornes M3E de référence (EDF, janvier 2025, p. 5)</span></div>}
{(view==='list'||view==='analysis')&&result?.stats&&<><div className="kpi-grid"><Metric title="Agents pris en compte" value={result.stats.agents}/><Metric title="NR moyen" value={result.stats.nrMean}/><Metric title="GF moyen" value={result.stats.gfMean}/><Metric title="Au moins 4 ans dans le NR" value={result.stats.fourYears}/></div>{result.stats.manualPresence>0&&<div className="notice">{result.stats.manualPresence} présence(s) confirmée(s) manuellement incluse(s) dans les effectifs et les moyennes. Les dernières anciennetés connues conservent leur date de référence.</div>}{result.stats.pending>0&&<div className="notice"><AlertCircle size={16}/>{result.stats.pending} lignes sans NNI : à rapprocher avant inclusion dans les analyses.</div>}</>}
{view==='list'&&<><div className="analysis-options agent-filters"><label className="search-label"><Search size={16}/><input aria-label="Rechercher un agent" placeholder="Nom, prénom ou NNI" value={q} onChange={e=>setQ(e.target.value)}/></label><label>Agence<select value={agency} onChange={e=>setAgency(e.target.value)}><option value="">Toutes</option>{result?.agencies?.map((a:string)=><option key={a}>{a}</option>)}</select></label><label>Collège<select value={college} onChange={e=>setCollege(e.target.value)}><option value="">Tous</option>{Object.entries(colleges).map(([k,v])=><option key={k} value={k}>{v}</option>)}</select></label><label>GF<input aria-label="Filtrer par GF" type="number" value={gf} onChange={e=>setGF(e.target.value)}/></label><label>NR<input aria-label="Filtrer par NR" type="number" value={nr} onChange={e=>setNR(e.target.value)}/></label><label>Années NR minimum<input aria-label="Ancienneté NR minimum" type="number" min={0} step={0.5} value={years} onChange={e=>setYears(e.target.value)}/></label><label>Trier<select value={sort} onChange={e=>setSort(e.target.value)}><option value="name">Nom</option><option value="nrYears">Ancienneté NR décroissante</option><option value="gfYears">Ancienneté GF décroissante</option><option value="nr">NR décroissant</option><option value="gf">GF décroissant</option></select></label></div><label className="archive-toggle"><input type="checkbox" checked={archive} onChange={e=>setArchive(e.target.checked)}/>Inclure les agents des fichiers antérieurs absents de cette photographie</label>
<section className="panel"><div className="panel-heading"><div><h2>{result?.total??0} fiches trouvées</h2><p>Les chiffres du haut et le tableau suivent les filtres appliqués à la photographie. Les archives restent hors des moyennes.</p></div><button className="btn" onClick={()=>csv('agents-ulm-page.csv',[['NNI','Nom','Plage M3E','GF','NR','Années GF','Années NR','Agence','Fichier','Anciennetés au','Présence manuelle','Motif'],...list.map((r:AgentRecord)=>[r.nni,r.name,m3eLabel(m3eKey(r)),r.gf,r.nr,r.gfYears,r.nrYears,r.agency,sources.find(s=>s.id===r.source)?.name,r.seniorityDate,r.manualPresence?'Oui':'Non',r.presenceNote])])}><Download size={15}/>Exporter cette page</button></div><div className="table-scroll"><table><thead><tr><th>Agent</th><th>Agence</th><th>Plage M3E</th><th>GF</th><th>NR</th><th>Années GF</th><th>Années NR</th><th>Présence dans le fichier</th><th/></tr></thead><tbody>{list.map((r:any)=><tr key={r.agentId}><td><b>{r.name}</b><small>{r.nni||'NNI à rapprocher'}</small></td><td>{fmt(r.agency)}<small>{colleges[r.college]||'Collège non renseigné'}</small></td><td>{m3eLabel(m3eKey(r))}</td><td>{fmt(r.gf)}</td><td>{fmt(r.nr)}</td><td>{fmt(r.gfYears)}</td><td>{fmt(r.nrYears)}</td><td><span className={'badge '+(r.source===source?'green':'amber')}>{r.manualPresence?'Présence confirmée manuellement':r.source===source?'Présent dans la liste':'Absent · historique conservé'}</span><small>{sources.find(s=>s.id===r.source)?.label}</small>{r.situations>1&&<small>{r.situations} lignes de situation</small>}{r.conflicts?.length>0&&<small>Valeurs divergentes à contrôler</small>}</td><td><button className="btn" onClick={()=>open(r.agentId)}><UserRound size={15}/>Fiche</button></td></tr>)}</tbody></table>{!list.length&&!busy&&<div className="empty">Aucun agent pour ces filtres.</div>}</div><Pager offset={offset} total={result?.total||0} size={100} onChange={setOffset}/></section></>}
{view==='hourly'&&result?.annual13Cents!==undefined&&<><HourlySummary data={result} months={13}/><HourlyIndividual data={result}/></>}
{view==='payroll'&&result?.annual13Cents!==undefined&&<PayrollSummary isAdmin={isAdmin} data={result} residence={residence} setResidence={setResidence} setGridRef={setGridRef} setBonusRef={setBonusRef} onOpen={open}/>}
{view==='families'&&result?.summaries&&<FamilyFocus data={result} agency={agency} setAgency={setAgency}/>}
{view==='analysis'&&result?.stats&&<AgentAnalysis stats={result.stats} label={active?.label||''}/>}
{view==='movements'&&result?.appeared&&<><div className="analysis-options"><label>Comparer avec<select value={previous||result.previous?.id||''} onChange={e=>setPrevious(e.target.value)}>{sources.filter(s=>s.id!==source&&s.status!=='review'&&s.date<(active?.date||'')).map(s=><option key={s.id} value={s.id}>{s.label}</option>)}</select></label></div><div className="kpi-grid"><Metric title="Apparitions observées" value={result.appeared.length}/><Metric title="Absences à qualifier" value={pendingAbsences.length}/><Metric title="Départs confirmés" value={confirmedAbsences.length}/><Metric title="Cadres dirigeants identifiés" value={executiveAbsences.length}/><Metric title="Réapparitions observées" value={result.reappeared.length}/><Metric title="Changements NR / GF / agence" value={result.changes.length}/></div><div className="notice"><AlertCircle size={16}/><span>{result.canInferAbsence?'Seules les disparitions entre les deux photographies sont à qualifier. Les GF 19 peuvent aussi être retrouvés depuis leur dernier fichier historique. Confirmer un départ conserve les données.':'Fichier partiel ou identités incomplètes : les absences ne peuvent pas servir à confirmer des départs.'}</span></div><div className="analysis-options"><label>Afficher les absences<select aria-label="Filtrer les absences selon leur confirmation" value={absenceFilter} onChange={e=>setAbsenceFilter(e.target.value as 'pending'|'confirmed'|'executives'|'all')}><option value="pending">À qualifier uniquement ({pendingAbsences.length})</option><option value="confirmed">Départs confirmés ({confirmedAbsences.length})</option><option value="executives">Classés cadres dirigeants ({executiveAbsences.length})</option><option value="all">Toutes les absences ({absences.length})</option></select></label><span className="filter-note">Les départs confirmés restent consultables et peuvent être remis à vérifier.</span></div><MovementTable title="Absents de la photographie sélectionnée" records={displayedAbsences} onOpen={open} decisions={result.decisions} source={source} enabled={isAdmin&&result.canInferAbsence} allowPresence={isAdmin} busy={busy} onDecision={decide}/><MovementTable title="Apparitions et réapparitions · pour information" records={[...result.appeared].sort((a:any,b:any)=>a.name.localeCompare(b.name,'fr',{sensitivity:'base'}))} onOpen={open} decisions={result.decisions} source={source} enabled={false} onDecision={decide}/><section className="panel"><div className="panel-heading"><h2>Évolutions observées entre fichiers</h2></div><div className="table-scroll"><table><thead><tr><th>Agent</th><th>GF avant / après</th><th>NR avant / après</th><th>Agence avant / après</th></tr></thead><tbody>{[...result.changes].sort((a:any,b:any)=>a.current.name.localeCompare(b.current.name,'fr',{sensitivity:'base'})).map((r:any)=><tr key={r.current.agentId}><td><button className="text-btn" onClick={()=>open(r.current.agentId)}>{r.current.name}</button></td><td>{fmt(r.previous.gf)} → {fmt(r.current.gf)}</td><td>{fmt(r.previous.nr)} → {fmt(r.current.nr)}</td><td>{fmt(r.previous.agency)} → {fmt(r.current.agency)}</td></tr>)}</tbody></table></div></section></>}
{view==='executives'&&<section className="panel"><div className="panel-heading"><div><h2>Registre distinct · cadres dirigeants ({result?.total||0})</h2><p>Hors effectifs statutaires et globaux, hors moyennes GF/NR et masse salariale calculée. Aucune présence n’est créée dans les photographies individuelles.</p></div></div>{isAdmin&&<form onSubmit={async e=>{e.preventDefault();const saved=await decide({kind:'executive_manual',agent:'exec-manual-'+crypto.randomUUID(),source,name:executiveName,origin:executiveOrigin,startDate:executiveDate,note:executiveNote});if(saved){setExecutiveName('');setExecutiveOrigin('');setExecutiveDate('');setExecutiveNote('');}}}><h3>Ajouter un cadre dirigeant provenant d’une autre entité</h3><div className="analysis-options"><label>Nom et prénom<input required maxLength={180} value={executiveName} onChange={e=>setExecutiveName(e.target.value)} placeholder="Nom et prénom"/></label><label>Entité d’origine<input maxLength={180} value={executiveOrigin} onChange={e=>setExecutiveOrigin(e.target.value)} placeholder="Entité précédente"/></label><label>Date d’arrivée<input type="date" value={executiveDate} onChange={e=>setExecutiveDate(e.target.value)}/></label><label>Précisions<input maxLength={400} value={executiveNote} onChange={e=>setExecutiveNote(e.target.value)}/></label></div><button className="btn primary" type="submit" disabled={busy||!executiveName.trim()}>Créer la fiche dirigeant</button></form>}<div className="table-scroll"><table><thead><tr><th>Cadre dirigeant</th><th>Origine</th><th>Date d’arrivée</th><th>Date de sortie</th><th>Origine de la fiche / précisions</th><th>Actions</th></tr></thead><tbody>{list.map((r:any)=><ExecutiveRegisterRow key={r.agentId} row={r} isAdmin={isAdmin} busy={busy} onOpen={open} onSave={decide}/>)}</tbody></table>{!list.length&&!busy&&<div className="empty">Aucun cadre dirigeant enregistré dans ce registre.</div>}</div></section>}
{isAdmin&&view==='identity'&&<section className="panel"><div className="panel-heading"><div><h2>Rapprochements · fiches sans NNI</h2><p>Retirer une fiche la masque de cette liste sans effacer les historiques. La corbeille permet de la restaurer.</p></div><button className="btn" disabled={busy} onClick={()=>{setDismissed(v=>!v);setChosenPending([]);setOffset(0);}}>{dismissed?'Afficher les rapprochements':'Corbeille / Restaurer'}</button></div><label className="search-label"><Search size={15}/><input placeholder="Rechercher un agent" value={q} onChange={e=>setQ(e.target.value)}/></label><div className="analysis-options"><label className="archive-toggle"><input type="checkbox" checked={list.length>0&&list.every((r:any)=>chosenPending.includes(r.id))} onChange={e=>setChosenPending(e.target.checked?list.map((r:any)=>r.id):[])}/>Sélectionner toutes les fiches de cette page</label><button className="btn" disabled={busy||!chosenPending.length} onClick={()=>archivePending(list.filter((r:any)=>chosenPending.includes(r.id)),dismissed?'restore':'dismiss')}>{dismissed?'Restaurer la sélection':'Retirer la sélection'} ({chosenPending.length})</button></div>{list.map((r:any)=><div key={r.id} className="identity-row"><label className="archive-toggle"><input type="checkbox" checked={chosenPending.includes(r.id)} onChange={e=>setChosenPending(v=>e.target.checked?[...v,r.id]:v.filter(id=>id!==r.id))}/>Sélectionner</label>{dismissed?<><div><b>{r.name}</b><small>GF {fmt(r.gf)} · NR {fmt(r.nr)} · ligne {r.row}</small></div><button className="btn" disabled={busy} onClick={()=>archivePending([r],'restore')}>Restaurer</button></>:<><IdentityRow row={r} busy={busy} onOpen={open} onLink={(target:string)=>decide({kind:'link',agent:r.agentId,target,source:r.source})}/><button className="btn" disabled={busy} onClick={()=>archivePending([r],'dismiss')}>Retirer</button></>}</div>)}{!list.length&&!busy&&<div className="empty">{dismissed?'La corbeille est vide.':'Aucun rapprochement en attente pour cette recherche.'}</div>}<Pager offset={offset} total={result?.total||0} size={60} onChange={setOffset}/></section>}
{isAdmin&&view==='imports'&&<>{review?<ImportReview review={review} onOpen={open} onBack={back} onValidated={async()=>{const id=review.meta.id;setReviewId('');setReview(null);await reload();setSource(id);onImported?.(id);setRevision(r=>r+1);setNotice('Import validé. Les photographies précédentes restent conservées.');}}/>:<><section className="panel"><h2>Ajouter des situations individuelles</h2><p>Le formulaire commun permet de choisir un bilan social ou un fichier de situations individuelles. Après vérification et validation, les analyses individuelles sont recalculées automatiquement.</p><button className="btn primary" onClick={()=>navigate({tab:'sources',importType:'agents',agentReview:'',agentProfile:'',socialReview:''})}><Upload size={16}/>Ajouter un fichier</button></section><section className="panel"><div className="panel-heading"><div><h2>Fichiers individuels et couverture</h2><p>19 photographies initiales, dont une version alternative 2024. Les originaux reçus sont conservés dans tes fichiers ; chaque donnée indique le classeur, la feuille et la ligne.</p></div></div><div className="table-scroll"><table><thead><tr><th>Date / période</th><th>Document et feuille</th><th>Lignes</th><th>Fiches</th><th>Traitement</th></tr></thead><tbody>{sources.map(s=><tr key={s.id}><td>{s.label}<small>{s.confidence}</small></td><td>{s.name}<small>{s.sheet}</small></td><td>{s.rows}</td><td>{s.agents}</td><td>{s.status==='review'?<button className="btn" onClick={()=>loadReview(s.id)}>Vérifier</button>:<span className="badge green">{s.status==='validated'?'Import validé':s.primary?'Source initiale':'Version alternative'}</span>}{s.status&&<a href={'/api/agents/files/'+s.id} className="text-btn">Original</a>}</td></tr>)}</tbody></table></div></section><section className="panel prose"><h2>Points de contrôle</h2><p>Dans les deux fichiers de 2022, le collège « Cadres » est déduit du GF lorsqu’il est égal ou supérieur à 12. Le GF et les autres données du fichier restent ceux de la source.</p><p>Sans fichier spécifiquement daté de 2015 ou 2021, aucun mouvement n’est daté précisément sur ces années. Les états préparatoires 2013 et 2015 reprennent les données de fin 2012 et fin 2014. La date d’octobre 2020 reste estimée. Les anciennetés du fichier 2009 sont renseignées au 31 décembre 2009.</p><p>Le fichier 2012 sans NNI reste à rapprocher. Les anciens NR courts sont conservés tels quels dans l’historique, sans conversion supposée. Les dates de fin en 2999 désignent une situation ouverte et ne sont pas des dates de départ.</p>{meta.issues.map((i:any,k:number)=><p key={k}>{i.text}</p>)}<p>Un nouveau fichier ne remplace pas les précédents. Une absence ne supprime jamais une fiche. L’outil expose des situations observées ; il ne déduit pas une discrimination ou un droit automatique à avancement.</p></section></> }</>}
</> }</div>;
}
function Metric({title,value}:{title:string;value:any}){return <section className="kpi"><div className="kpi-title">{title}</div><div className="kpi-value">{fmt(value)}</div></section>;}
function Pager({offset,total,size,onChange}:{offset:number;total:number;size:number;onChange:(n:number)=>void}){return <div className="pagination"><span>{total?offset+1:0}–{Math.min(offset+size,total)} / {total}</span><button className="btn" disabled={!offset} onClick={()=>onChange(Math.max(0,offset-size))}>Précédent</button><button className="btn" disabled={offset+size>=total} onClick={()=>onChange(offset+size)}>Suivant</button></div>;}
function IdentityRow({row,busy,onOpen,onLink}:{row:any;busy:boolean;onOpen:(id:string)=>void;onLink:(id:string)=>void}){const [target,setTarget]=useState(row.candidates?.length===1?row.candidates[0].nni:'');return <div className="identity-row"><div><b>{row.name}</b><small>Janvier 2012 · GF {fmt(row.gf)} · NR {fmt(row.nr)} · ligne {row.row}</small></div><label>NNI proposé ou choisi<input aria-label={'NNI pour '+row.name} placeholder="NNI existant" list={'candidates-'+row.row} value={target} onChange={e=>setTarget(e.target.value.toUpperCase())}/><datalist id={'candidates-'+row.row}>{row.candidates?.map((c:any)=><option key={c.nni} value={c.nni}>{c.name}</option>)}</datalist></label><button className="btn" disabled={!target} onClick={()=>onOpen(target)}>Vérifier la fiche</button><button className="btn primary" disabled={!target||busy} onClick={()=>onLink(target)}><Check size={15}/>Valider le NNI</button></div>;}
function ExecutiveRegisterRow({row:r,isAdmin,busy,onOpen,onSave}:any){
 const [editing,setEditing]=useState(false);
 const [name,setName]=useState(r.name||'');
 const [origin,setOrigin]=useState(r.origin||'');
 const [startDate,setStartDate]=useState(r.startDate||'');
 const [exitDate,setExitDate]=useState(r.exitDate||'');
 const [note,setNote]=useState(r.note||'');
 const cancel=()=>{setEditing(false);setName(r.name||'');setOrigin(r.origin||'');setStartDate(r.startDate||'');setExitDate(r.exitDate||'');setNote(r.note||'');};
 return <tr><td>{editing?<input aria-label="Nom du cadre dirigeant" required maxLength={180} value={name} onChange={e=>setName(e.target.value)}/>:<><b>{r.name}</b><small>{r.note}</small>{r.exitDate&&<small>Sorti de l’unité</small>}</>}</td><td>{editing?<input aria-label="Entité d’origine" maxLength={180} value={origin} onChange={e=>setOrigin(e.target.value)}/>:r.origin||'Non renseignée'}</td><td>{editing?<input aria-label="Date d’arrivée" type="date" value={startDate} onChange={e=>setStartDate(e.target.value)}/>:r.startDate?date(r.startDate):'Non renseignée'}</td><td>{editing?<input aria-label="Date de sortie" type="date" min={startDate||undefined} value={exitDate} onChange={e=>setExitDate(e.target.value)}/>:r.exitDate?date(r.exitDate):'Toujours dans l’unité / non renseignée'}</td><td>{editing?<textarea aria-label="Précisions" maxLength={1000} value={note} onChange={e=>setNote(e.target.value)}/>:r.manual?'Fiche créée manuellement':'Ancienne fiche individuelle · GF '+fmt(r.gf)}</td><td>{!editing&&<>{!r.manual&&<button className="btn" onClick={()=>onOpen(r.agentId)}>Historique</button>}{isAdmin&&<button className="btn" disabled={busy} onClick={()=>setEditing(true)}>Modifier la fiche</button>}{isAdmin&&<button className="text-btn" disabled={busy} onClick={()=>{if(window.confirm('Retirer cette personne du registre des cadres dirigeants ? Son historique éventuel sera conservé.'))onSave({kind:'executive_remove',agent:r.agentId,source:r.source});}}>Retirer du registre</button>}</>}{editing&&<><button className="btn primary" disabled={busy||!name.trim()||!!(exitDate&&startDate&&exitDate<startDate)} onClick={async()=>{const ok=await onSave({kind:'executive_update',agent:r.agentId,source:r.source,name,origin,startDate,exitDate,note});if(ok)setEditing(false);}}>Enregistrer</button><button className="text-btn" onClick={cancel}>Annuler</button></>}</td></tr>;
}
function MovementTable({title,records,onOpen,decisions,source,enabled,allowPresence=false,busy,onDecision}:any){return <section className="panel"><div className="panel-heading"><h2>{title} ({records.length})</h2></div><div className="table-scroll"><table><thead><tr><th>Agent</th><th>Dernière situation observée</th><th>Décision</th><th>Actions</th></tr></thead><tbody>{records.map((r:any)=><MovementRow key={source+':'+r.agentId} row={r} decision={decisions?.filter((d:any)=>d.agent===r.agentId&&d.source===source&&['departure','return','absence','executive','executive_remove'].includes(d.kind)).at(-1)} {...{source,enabled,allowPresence,busy,onDecision,onOpen}}/>)}</tbody></table>{!records.length&&<div className="empty">Aucun mouvement dans cette catégorie.</div>}</div></section>;}
function MovementRow({row:r,decision:d,source,enabled,allowPresence,busy,onDecision,onOpen}:any){
 const [editing,setEditing]=useState(false);const [gf,setGF]=useState(String(r.gf??''));const [nr,setNR]=useState(String(r.nr??''));const [agency,setAgency]=useState(r.agency||'');const [note,setNote]=useState('');
 let detail:any={};try{detail=JSON.parse(d?.note||'');}catch{}
 return <tr><td><button className="text-btn" onClick={()=>onOpen(r.agentId)}>{r.name}</button><small>{r.nni}</small></td><td>GF {fmt(r.gf)} · NR {fmt(r.nr)}<small>{r.agency}</small></td><td>{d?d.kind==='departure'?'Départ confirmé':d.kind==='return'?'Présence confirmée · continuité active':d.kind==='executive'?'Cadre dirigeant · hors effectifs':'Absence en attente':r.manualPresence?'Présence confirmée · continuité active':'À confirmer'}{d?.note&&<small>{detail.presence?detail.note:d.note}</small>}{detail.presence&&<small>GF {detail.presence.gf} · NR {detail.presence.nr} · {detail.presence.agency}</small>}</td><td>
 {allowPresence&&<button className="btn primary" disabled={busy} onClick={()=>setEditing(!editing)}>Confirmer la présence</button>}
 {editing&&<form onSubmit={async e=>{e.preventDefault();await onDecision({kind:'return',agent:r.agentId,source,note,presence:{gf:Number(gf),nr:Number(nr),agency}});}}><p>Présence à la date de cette photographie, prolongée jusqu’à une nouvelle observation ou décision. Vérifier les dernières valeurs connues.</p><div className="analysis-options"><label>GF<input required type="number" min="1" max="30" step="1" value={gf} onChange={e=>setGF(e.target.value)}/></label><label>NR<input required type="number" min="1" max="1000" step="1" value={nr} onChange={e=>setNR(e.target.value)}/></label><label>Agence<input maxLength={180} value={agency} onChange={e=>setAgency(e.target.value)}/></label><label>Motif / élément de confirmation<input required maxLength={1000} placeholder="Ex. présence vérifiée auprès de l’agent" value={note} onChange={e=>setNote(e.target.value)}/></label></div><p>Les anciennetés restent datées de leur dernière source connue. Un changement de GF ou NR sans date d’effet ne crée pas de temps de passage.</p><button className="btn primary" disabled={busy||!note.trim()} type="submit">Enregistrer la présence</button><button className="text-btn" type="button" onClick={()=>setEditing(false)}>Annuler</button></form>}
 {enabled&&r.gf===19&&d?.kind!=='executive'&&<button className="btn" disabled={busy} onClick={()=>{if(window.confirm('Classer cet ancien GF 19 comme cadre dirigeant ? La fiche restera hors des effectifs et pourra être retirée de cette catégorie.'))onDecision({kind:'executive',agent:r.agentId,source,note:'Évolution vers un poste de cadre dirigeant, à confirmer par les informations de carrière.'});}}>Cadre dirigeant</button>}{enabled&&d?.kind!=='departure'&&d?.kind!=='executive'&&<button className="btn" disabled={busy} onClick={()=>onDecision({kind:'departure',agent:r.agentId,source,note:'Départ confirmé par le propriétaire après examen des fichiers.'})}>Confirmer le départ</button>}
 {allowPresence&&<button className="text-btn" disabled={busy} onClick={()=>onDecision({kind:d?.kind==='executive'?'executive_remove':'absence',agent:r.agentId,source})}>Laisser à vérifier / annuler la confirmation</button>}
 </td></tr>;
}
function AgentAnalysis({stats,label}:any){const plot=(values:any,key:string)=>Object.entries(values).map(([x,count])=>({[key]:Number(x),count})).sort((a:any,b:any)=>a[key]-b[key]);return <><M3eTable rows={stats.m3eMeans||[]}/><p className="gap-method">Les repères de progression ci-dessous concernent les agents sélectionnés dans le fichier actuel ; leur historique peut inclure des périodes dans une autre plage M3E.</p><ProgressionTables data={stats.progression}/><p className="gap-method">{label} · Agents de la photographie suivant les filtres appliqués. Moyennes arithmétiques non pondérées par le taux de travail. Les identités non rapprochées sont exclues.</p><div className="overview-grid">{[['gfDistribution','GF'],['nrDistribution','NR']].map(([key,label])=><section className="panel" key={key}><div className="panel-heading"><h2>Répartition par {label}</h2></div><div className="chart-scroll"><div className="chart"><ResponsiveContainer width="100%" height="100%"><BarChart data={plot(stats[key],label)}><CartesianGrid vertical={false}/><XAxis dataKey={label}/><YAxis allowDecimals={false}/><Tooltip formatter={(v:any)=>[v,'Agents']}/><Bar dataKey="count" fill="#123b36"/></BarChart></ResponsiveContainer></div></div></section>)}</div><section className="panel"><div className="panel-heading"><h2>Effectifs par collège renseigné</h2></div>{Object.entries(stats.colleges).map(([key,v])=><p key={key}>{colleges[key]||key} : <b>{fmt(v)}</b></p>)}</section></>;}
function AgentProfile({isAdmin,profile,preferred,sources,onBack,onDecision,gridRef,bonusRef,residence}:any){const [chosen,setChosen]=useState(profile.snapshots.some((s:any)=>s.source.id===preferred)?preferred:profile.snapshots[0]?.source.id||'');const [detail,setDetail]=useState(false);const [calculationDate,setCalculationDate]=useState('');const [benchmark,setBenchmark]=useState<any>(null);const snap=profile.snapshots.find((s:any)=>s.source.id===chosen)||profile.snapshots[0];const r=snap?.situation||{};const sr=snap?.source;const rows=profile.records.filter((x:any)=>x.source===chosen);const points=profile.snapshots.filter((s:any)=>s.source.primary||s.source.status==='validated').slice().reverse().map((s:any)=>({date:s.source.date,label:s.source.label,nr:s.situation?.nr??null,gf:s.situation?.gf??null}));const source=(id:string)=>sources.find((s:any)=>s.id===id);const calculationAsOf=calculationDate||(sr?.date||'');const career=careerSeniority(profile.records,sources,calculationAsOf,chosen);useEffect(()=>setCalculationDate(''),[chosen]);useEffect(()=>{setBenchmark(null);const c=new AbortController();api('/api/agents?view=progression&source='+encodeURIComponent(chosen),{signal:c.signal}).then(setBenchmark).catch(()=>{});return()=>c.abort();},[chosen]);
return <><button className="text-btn" onClick={onBack}><ArrowLeft size={16}/>Retour aux agents</button><section className="panel agent-profile-head"><div><div className="eyebrow">FICHE INDIVIDUELLE · HISTORIQUE CONSERVÉ</div><h2>{r.name||profile.records.at(-1)?.name||profile.id}</h2><p>NNI : {r.nni||'non rapproché'} · {fmt(r.agency)} · {colleges[r.college]||'Collège non renseigné dans cette source'}</p></div><button className="btn" onClick={()=>csv('fiche-agent-'+profile.id+'.csv',[['Document','Date de référence','Ligne','GF','NR','Années GF','Années NR','Ancienneté IEG publiée','Anciennetés publiées au','Agence','Date calcul carrière','Ancienneté carrière calculée','Méthode carrière'],...profile.records.map((r:AgentRecord)=>[source(r.source)?.name,source(r.source)?.date,r.row,r.gf,r.nr,r.gfYears,r.nrYears,r.iegYears,r.seniorityDate,r.agency,calculationAsOf,career?.years,career?.method])])}><Download size={15}/>Exporter les situations</button></section><div className="analysis-options"><label>Situation consultée<select value={chosen} onChange={e=>setChosen(e.target.value)}>{profile.snapshots.map((s:any)=><option key={s.source.id} value={s.source.id}>{s.source.label}</option>)}</select></label><span className="filter-note">Anciennetés au {date(r.seniorityDate||sr?.seniorityDate)} · aucune prolongation automatique</span></div><div className="kpi-grid">{r.manualPresence&&<div className="notice">Présence confirmée manuellement · {r.presenceNote} · valeurs reprises ou renseignées lors de la confirmation.</div>}<Metric title="NR observé" value={r.nr}/><Metric title="GF observé" value={r.gf}/><Metric title="Années dans le NR" value={r.nrYears}/><Metric title="Années dans le GF" value={r.gfYears}/></div><AgentRemuneration agentId={profile.id} source={chosen} grid={gridRef} bonus={bonusRef} residence={residence}/><ProgressionSummary data={benchmark} gf={r.gf} nr={r.nr}/><section className="panel agent-career"><div className="panel-heading"><div><h2>Ancienneté de carrière recalculée</h2><p>Prolongation de l’ancienneté connue, en supposant une carrière continue. Une absence d’un fichier ne remet pas l’ancienneté à zéro.</p></div><label>Date de calcul<input aria-label="Date de calcul de l’ancienneté carrière" type="date" value={calculationAsOf} onChange={e=>setCalculationDate(e.target.value)}/></label></div><div className="agent-career-value">{career?.completedYears!==null&&career?.completedYears!==undefined?`${career.completedYears} ans`:'Non calculable'}<span>{career?.years!==null&&career?.years!==undefined?`${fmt(career.years)} années · au ${date(calculationAsOf)}`:''}</span></div>{career&&<><p><span className={'badge '+(career.estimated||career.conflict?'amber':'green')}>{career.method}</span></p><p>{career.base>0?`${fmt(career.base)} ans publiés au ${date(career.start)}, puis ajout du temps écoulé.`:`Point de départ : ${date(career.start)}.`}</p><p className="gap-method">Source du point de départ : {career.rupEvidence?.map((r:any)=>r.source+' · '+r.sheet+' · ligne '+r.row).join(' ; ')||source(career.evidence.source)?.name} · feuille « {source(career.evidence.source)?.sheet} » · ligne {career.evidence.row}. Première apparition observée : {date(career.firstSeen)}.{career.estimated?' La date d’entrée manque : cette estimation suit l’hypothèse d’une carrière commencée à la première apparition, et peut sous-estimer l’ancienneté réelle.':''}{career.conflict?' Les données de carrière ou les contrats divergent : aucun résultat arbitraire n’est retenu.':''}</p></> }<details><summary>Méthode du calcul</summary><p>Priorité à la date d’entrée IEG cohérente des RUP, rapprochée par NNI et contrat. En cas de contradiction ou de contrat ambigu, les anciennetés fiables issues des fichiers individuels restent exploitables ; sinon le calcul reste à vérifier. Sans date RUP exploitable, utilisation de la dernière ancienneté IEG publiée avant la date de calcul, puis de la date d’entrée IEG ou entreprise renseignée. Sinon, première apparition dans les fichiers reçus comme estimation. Le nombre affiché correspond aux années révolues ; les valeurs publiées restent conservées séparément.</p></details></section><section className="panel"><div className="agent-detail-grid">{[['Ancienneté IEG publiée dans ce fichier',r.iegYears!==undefined?fmt(r.iegYears)+' ans':'Non renseignée dans cette source'],['Arrivée dans l’unité',date(r.entryUnit)],['Entrée entreprise',date(r.entryCompany)],['Date d’effet du GF',date(r.gfDate)],['Date d’effet du NR',date(r.nrDate)],['Taux de travail',fmt(r.coefficient)],['Emploi',fmt(r.job)],['Plage M3E',fmt(r.m3e)]].map(([label,value])=><div key={label}><small>{label}</small><b>{value}</b></div>)}</div><p className="gap-method">{sr?.name} · feuille « {sr?.sheet} » · lignes {rows.map((r:any)=>r.row).join(', ')}. {r.conflicts?.length?'Des situations divergent : aucune valeur arbitraire n’a été retenue.':''}</p><button className="text-btn" onClick={()=>setDetail(!detail)}>{detail?'Masquer':'Afficher'} les {rows.length} lignes de situation</button>{detail&&<div className="table-scroll"><table><thead><tr><th>Ligne</th><th>GF</th><th>NR</th><th>Années GF</th><th>Années NR</th><th>Taux</th><th>Agence / équipe</th><th>Indication de présence source</th></tr></thead><tbody>{rows.map((r:any)=><tr key={r.id}><td>{r.row}</td><td>{fmt(r.gf)}</td><td>{fmt(r.nr)}</td><td>{fmt(r.gfYears)}</td><td>{fmt(r.nrYears)}</td><td>{fmt(r.coefficient)}</td><td>{r.agency}<small>{r.team}</small></td><td>{fmt(r.presence)}</td></tr>)}</tbody></table></div>}</section>
<section className="panel"><div className="panel-heading"><div><h2>NR et GF observés au fil des fichiers</h2><p>Points aux dates des photographies. Une absence de donnée laisse un blanc.</p></div></div><div className="chart-scroll"><div className="chart"><ResponsiveContainer width="100%" height="100%"><LineChart data={points} margin={{bottom:20,right:10,left:0}}><CartesianGrid vertical={false}/><XAxis dataKey="date" interval={0} angle={-45} height={65} textAnchor="end" tick={{fontSize:10}} tickFormatter={v=>String(v).slice(0,7)}/><YAxis yAxisId="nr" stroke="#123b36" label={{value:'NR',angle:-90,position:'insideLeft'}}/><YAxis yAxisId="gf" orientation="right" stroke="#ba372b" label={{value:'GF',angle:90,position:'insideRight'}}/><Tooltip labelFormatter={(_,p)=>p?.[0]?.payload?.label||''}/><Legend/><Line name="NR" yAxisId="nr" dataKey="nr" stroke="#123b36" connectNulls={false}/><Line name="GF" yAxisId="gf" dataKey="gf" stroke="#ba372b" connectNulls={false}/></LineChart></ResponsiveContainer></div></div></section>
{profile.rup?.length>0&&<section className="panel"><h2>Historique RUP · données de carrière</h2><p>Rapprochement par NNI et contrat. Les dates d’entrée IEG cohérentes sont prioritaires pour les anciennetés et les calculs de rémunération, y compris pour les situations historiques. Les adresses personnelles sont exclues.</p><div className="table-scroll"><table><thead><tr><th>Source</th><th>Contrat</th><th>Entrée IEG</th><th>Entrée unité</th><th>Agence / emploi</th></tr></thead><tbody>{profile.rup.map((x:any,i:number)=><tr key={i}><td>{x.source}<small>{x.sheet} · ligne {x.row}</small></td><td>{x.contrat}</td><td>{date(x.entreeIEG)}</td><td>{date(x.entreeUnite)}</td><td>{x.agence}<small>{x.emploi}</small></td></tr>)}</tbody></table></div></section>}
<section className="panel"><div className="panel-heading"><div><h2>Situations enregistrées</h2><p>Une fiche peut avoir plusieurs situations dans un même fichier.</p></div></div><div className="table-scroll"><table><thead><tr><th>Photographie</th><th>GF</th><th>NR</th><th>Années GF</th><th>Années NR</th><th>Ancienneté IEG</th><th>Lignes</th></tr></thead><tbody>{profile.snapshots.map((s:any)=><tr key={s.source.id}><td><button className="text-btn" onClick={()=>setChosen(s.source.id)}>{s.source.label}</button><small>Anciennetés au {date(s.source.seniorityDate)}</small></td><td>{fmt(s.situation?.gf)}</td><td>{fmt(s.situation?.nr)}</td><td>{fmt(s.situation?.gfYears)}</td><td>{fmt(s.situation?.nrYears)}</td><td>{fmt(s.situation?.iegYears)}</td><td>{s.situation?.situations}</td></tr>)}</tbody></table></div></section>
<section className="panel"><div className="panel-heading"><div><h2>Événements historiques ({profile.events.length})</h2><p>Les NR anciens restent dans leur format source. Les blocs modernes décrivent des motifs et des périodes ; leur NR de contexte n’est pas présenté comme un NR acquis à la date de l’événement.</p></div></div><div className="table-scroll"><table><thead><tr><th>Date / période</th><th>Motif source</th><th>GF historique</th><th>NR historique brut</th><th>Nombre de NR déclaré</th><th>Sources</th></tr></thead><tbody>{profile.events.map((e:any,i:number)=><tr key={i}><td>{date(e.date)}{e.openEnd&&<small>Situation ouverte dans la source</small>}{e.end&&<small>Fin : {date(e.end)}</small>}</td><td>{e.motif}<small>{e.kind}</small></td><td>{fmt(e.gf)}</td><td>{fmt(e.nrRaw)}{e.legacyNR&&<small>Ancien format · conversion à vérifier</small>}</td><td>{fmt(e.numberNR)}</td><td><details><summary>{e.evidence.length} références</summary>{e.evidence.map((ev:any,j:number)=><small key={j}>{source(ev.source)?.name} · {ev.sheet} · ligne {ev.row}{ev.column?' · colonne '+ev.column:''}</small>)}</details></td></tr>)}</tbody></table>{!profile.events.length&&<div className="empty">Aucun événement historique détaillé reçu pour cette identité.</div>}</div></section>
{profile.decisions.length>0&&<section className="panel"><h2>Décisions et rapprochements</h2>{profile.decisions.map((d:any)=><p key={d.id}>{d.kind==='link'?'Rapprochement validé':d.kind==='departure'?'Départ confirmé':d.kind==='absence'?'Absence à vérifier':d.kind==='return'?'Présence confirmée':d.kind} · {source(d.source)?.label} · {decisionNote(d.note)}{isAdmin&&d.kind==='link'&&<button className="text-btn" onClick={()=>onDecision({kind:'unlink',agent:d.agent,source:d.source})}>Annuler ce rapprochement</button>}</p>)}</section>}</>;
}
export function AgentImport({sources,onUploaded}:{sources:AgentSource[];onUploaded:(id:string)=>void}){const [file,setFile]=useState<File|null>(null);const [sheets,setSheets]=useState<{name:string;rows:unknown[][]}[]>([]);const [sheet,setSheet]=useState(0);const [header,setHeader]=useState(0);const [mapping,setMapping]=useState<Record<string,number>>({});const [reference,setReference]=useState('');const [seniority,setSeniority]=useState('');const [complete,setComplete]=useState(false);const [busy,setBusy]=useState(false);const [error,setError]=useState('');
const selected=sheets[sheet];const headers=(selected?.rows[header]||[]).map(String);const proposed=selected?mapAgentRows(selected.rows,mapping,header,seniority||reference):[];
const prepare=(all:{name:string;rows:unknown[][]}[],i:number,h?:number)=>{const rows=all[i].rows;const row=h??Math.max(0,rows.slice(0,40).findIndex(r=>r.some(c=>/\bNNI\b/.test(normalName(c)))));setSheet(i);setHeader(row);const saved=(sources.filter((s:any)=>s.mapping).at(-1) as any)?.mapping||{};setMapping(detectMapping((rows[row]||[]).map(String),saved));};
const read=async(f?:File)=>{if(!f)return;setBusy(true);setError('');try{const s=await readAgentWorkbook(f);setFile(f);setSheets(s);const preferred=Math.max(0,s.findIndex(s=>/Requete El.m.nts de carri.re|^El.m.nts de carri.re$/i.test(s.name)));prepare(s,preferred);}catch(e){setError('Lecture impossible : '+(e as Error).message+'. Si le fichier est chiffré, fournir une copie déverrouillée.');}finally{setBusy(false);}};
const send=async()=>{if(!file||!reference)return;setBusy(true);setError('');try{if(proposed.length>10000)throw Error('Sélectionner la feuille de situations actuelles, limitée à 10 000 lignes.');const f=new FormData();f.append('file',file);f.append('extraction',JSON.stringify({date:reference,seniorityDate:seniority||reference,complete,sheet:selected.name,mapping:Object.fromEntries(importFields.map(([k])=>[k,headers[mapping[k]]||''])),records:proposed}));const saved=await api('/api/agents/import',{method:'POST',body:f});onUploaded(saved.id);}catch(e){setError((e as Error).message);}finally{setBusy(false);}};
return <section className="panel"><div className="panel-heading"><div><h2>Ajouter un fichier individuel</h2><p>Excel XLS, XLSX, XLSM ou CSV · 20 Mo. Associer les colonnes, examiner les propositions, puis valider. Les macros ne sont pas exécutées.</p></div><label className="btn primary file-input"><Upload size={16}/>{busy?'Lecture…':'Choisir un fichier'}<input type="file" accept=".xls,.xlsx,.xlsm,.csv" disabled={busy} onChange={e=>read(e.target.files?.[0])}/></label></div>{error&&<div className="notice"><AlertCircle size={15}/>{error}</div>}{file&&<><p><b>{file.name}</b></p><div className="analysis-options"><label>Feuille<select value={sheet} onChange={e=>prepare(sheets,+e.target.value)}>{sheets.map((s,i)=><option key={i} value={i}>{s.name}</option>)}</select></label><label>Ligne des titres<input type="number" min={1} max={selected.rows.length} value={header+1} onChange={e=>prepare(sheets,sheet,Math.max(0,+e.target.value-1))}/></label><label>Date de la photographie<input type="date" value={reference} onChange={e=>setReference(e.target.value)}/></label><label>Anciennetés renseignées au<input type="date" value={seniority||reference} onChange={e=>setSeniority(e.target.value)}/></label></div><div className="import-mapping">{importFields.map(([field,label])=><label key={field}>{label}{['name','gf','nr'].includes(field)?' *':''}<select value={mapping[field]??-1} onChange={e=>setMapping(m=>({...m,[field]:+e.target.value}))}><option value={-1}>Non renseigné</option>{headers.map((h,i)=><option key={i} value={i}>Colonne {i+1} · {h||'(sans titre)'}</option>)}</select></label>)}</div><label className="archive-toggle"><input type="checkbox" checked={complete} onChange={e=>setComplete(e.target.checked)}/>Ce fichier couvre l’ensemble de l’unité à cette date (sinon, il sera marqué partiel et ne servira pas à confirmer des absences).</label><p>{proposed.length} lignes proposées · {new Set(proposed.filter(r=>r.nni).map(r=>r.nni)).size} NNI distincts · {proposed.filter(r=>!r.nni).length} lignes à identifier.</p><div className="table-scroll"><table><thead><tr><th>Ligne</th><th>Agent</th><th>NNI</th><th>GF</th><th>NR</th><th>Années GF</th><th>Années NR</th></tr></thead><tbody>{proposed.slice(0,8).map(r=><tr key={r.id}><td>{r.row}</td><td>{r.name}</td><td>{r.nni||'À identifier'}</td><td>{fmt(r.gf)}</td><td>{fmt(r.nr)}</td><td>{fmt(r.gfYears)}</td><td>{fmt(r.nrYears)}</td></tr>)}</tbody></table></div><button className="btn primary" disabled={busy||!reference||!proposed.length||['name','gf','nr'].some(k=>mapping[k]===undefined||mapping[k]<0)} onClick={send}>Enregistrer pour vérification</button></>}</section>;
}
export function ImportReview({review,onOpen,onBack,onValidated}:any){const [busy,setBusy]=useState(false);const [error,setError]=useState('');const [checked,setChecked]=useState(false);const confirm=async()=>{setBusy(true);try{await api('/api/agents/import/'+review.meta.id,{method:'POST'});await onValidated();}catch(e){setError((e as Error).message);}finally{setBusy(false);}};return <section className="panel"><button className="text-btn" onClick={onBack}><ArrowLeft size={15}/>Retour aux imports</button><h2>{review.meta.name}</h2><p>Photographie du {date(review.meta.date)} · {review.records.length} situations. {review.meta.complete?'Unité entière déclarée':'Fichier déclaré partiel'}.</p><div className="kpi-grid"><Metric title="Apparitions à qualifier" value={review.pairs.appeared.length}/><Metric title="Absences à qualifier" value={review.pairs.absent.length}/><Metric title="Changements observés" value={review.pairs.changes.length}/><Metric title="Lignes sans NNI" value={review.records.filter((r:any)=>!r.nni).length}/></div><p>La validation ajoute une photographie. Elle ne supprime aucun agent, ne confirme aucun départ et ne remplace pas les fichiers précédents.</p><a href={'/api/agents/files/'+review.meta.id} className="btn">Télécharger l’original</a><div className="table-scroll"><table><thead><tr><th>Ligne</th><th>Agent / NNI</th><th>GF</th><th>NR</th><th>Années GF</th><th>Années NR</th></tr></thead><tbody>{review.records.slice(0,100).map((r:any)=><tr key={r.id}><td>{r.row}</td><td>{r.name}<small>{r.nni||'À rapprocher'}</small></td><td>{m3eLabel(m3eKey(r))}</td><td>{fmt(r.gf)}</td><td>{fmt(r.nr)}</td><td>{fmt(r.gfYears)}</td><td>{fmt(r.nrYears)}</td></tr>)}</tbody></table></div><p>Premières {Math.min(100,review.records.length)} lignes affichées. Après validation, les fiches, moyennes NR / GF, temps de passage, anciennetés et mouvements sont mis à jour automatiquement.</p>{review.meta.status==='review'&&<><label className="archive-toggle"><input type="checkbox" checked={checked} onChange={e=>setChecked(e.target.checked)}/>J’ai vérifié les colonnes, la date et le périmètre du fichier.</label><button className="btn primary" disabled={busy||!checked} onClick={confirm}><Check size={16}/>Valider cette photographie</button></>}{error&&<div className="notice">{error}</div>}</section>;}

function PassageValue({row}:any){return <>{row?.mean!==null&&row?.mean!==undefined?`${fmt(row.mean)} ans`:'Non calculable'}<small>{row?.count||0} passages retenus{row?.estimated?` · ${row.estimated} durées estimées`:''}</small></>;}
function ProgressionSummary({data,gf,nr}:any){if(!data)return null;const g=data.gfGroups.find((v:any)=>v.level===gf),n=data.nrGroups.find((v:any)=>v.level===nr),avg=data.nrByGF.find((v:any)=>v.gf===gf);return <section className="panel"><div className="panel-heading"><div><h2>Repères collectifs pour cette situation</h2><p>Historique disponible jusqu’au {date(data.to)} · moyennes des passages observés.</p></div></div><div className="agent-detail-grid"><div><small>Temps moyen du GF {fmt(gf)} vers un GF supérieur</small><b><PassageValue row={g}/></b></div><div><small>Temps moyen du NR {fmt(nr)} vers un NR supérieur</small><b><PassageValue row={n}/></b></div><div><small>NR moyen du GF {fmt(gf)}</small><b>{fmt(avg?.mean)}</b><small>{avg?.count||0} agents avec NR renseigné dans la photographie consultée</small></div></div><p className="gap-method">Ces repères collectifs ne prédisent pas la date du prochain avancement individuel. Le détail et la méthode sont disponibles dans « Analyses NR / GF ».</p></section>;}
function ProgressionTables({data}:any){if(!data)return null;return <><section className="panel"><div className="panel-heading"><div><h2>Temps de passage moyen au niveau supérieur</h2><p>Du {date(data.from)} au {date(data.to)} · ensemble des identités rapprochées dans les fichiers de référence.</p></div><button className="btn" onClick={()=>csv('temps-passage-gf-nr.csv',[['Type','Niveau de départ','Durée moyenne en années','Passages retenus','Durées estimées'],...['gf','nr'].flatMap(k=>data[k+'Groups'].map((r:any)=>[k.toUpperCase(),r.level,r.mean,r.count,r.estimated]))])}><Download size={15}/>Exporter</button></div><div className="agent-detail-grid"><div><small>Passage vers un GF supérieur · tous GF</small><b><PassageValue row={data.gf}/></b></div><div><small>Passage vers un NR supérieur · tous NR</small><b><PassageValue row={data.nr}/></b></div></div><details><summary>Méthode et limites des moyennes</summary><p>Une durée correspond au temps passé au niveau de départ avant une hausse observée pour le même NNI. Elle est calculée entre les dates d’effet du niveau précédent et du nouveau niveau. À défaut, une date est estimée à partir de l’ancienneté GF ou NR publiée et de sa date de référence. Sans deux dates utilisables, le passage est exclu.</p><p>Les données vont jusqu’à la photographie sélectionnée. Les fichiers de référence et les nouveaux imports validés, y compris partiels, sont utilisés pour les parcours ; les versions alternatives, identités non rapprochées et valeurs divergentes sont exclues. Un saut de plusieurs niveaux constitue un seul passage vers un niveau supérieur. Des évolutions intermédiaires peuvent manquer entre deux fichiers. Les agents encore au même niveau ne sont pas inclus : cette moyenne porte sur les passages réalisés, pas sur le temps d’attente de tous les agents.</p></details></section><div className="overview-grid">{[['gf','GF'],['nr','NR']].map(([key,label])=><section className="panel" key={key}><div className="panel-heading"><h2>Temps moyen par {label} de départ</h2></div><div className="table-scroll"><table><thead><tr><th>{label}</th><th>Vers un {label} supérieur</th><th>Passages</th><th>Durées estimées</th></tr></thead><tbody>{data[key+'Groups'].map((r:any)=><tr key={r.level}><td>{r.level}</td><td>{fmt(r.mean)} ans</td><td>{r.count}</td><td>{r.estimated}</td></tr>)}</tbody></table>{!data[key+'Groups'].length&&<div className="empty">Aucun passage calculable dans cet historique.</div>}</div></section>)}</div><section className="panel"><div className="panel-heading"><div><h2>NR moyen pour chaque GF</h2><p>Photographie sélectionnée, présences confirmées incluses · une voix par NNI, sans pondération par le taux de travail.</p></div><button className="btn" onClick={()=>csv('nr-moyen-par-gf.csv',[['GF','NR moyen','Agents avec NR renseigné','Agents du GF'],...data.nrByGF.map((r:any)=>[r.gf,r.mean,r.count,r.agents])])}><Download size={15}/>Exporter</button></div><div className="table-scroll"><table><thead><tr><th>GF</th><th>NR moyen</th><th>Agents avec NR renseigné</th><th>Agents du GF</th></tr></thead><tbody>{data.nrByGF.map((r:any)=><tr key={r.gf}><td>{r.gf}</td><td>{fmt(r.mean)}</td><td>{r.count}</td><td>{r.agents}</td></tr>)}</tbody></table></div></section></>;}

function PayrollSummary({isAdmin,data,residence,setResidence,setGridRef,setBonusRef,onOpen}:any){
 const [months,setMonths]=useState(13);const [details,setDetails]=useState(false);const [nameQuery,setNameQuery]=useState('');
 const detailRows=useMemo(()=>[...data.rows].sort((a:any,b:any)=>String(a.name||'').localeCompare(String(b.name||''),'fr',{sensitivity:'base'})||String(a.nni||'').localeCompare(String(b.nni||''),'fr')).map((r:any)=>({...r,hourly:hourlyRates([r],months)})),[data.rows,months]);
 const filteredRows=useMemo(()=>{const words=normalName(nameQuery).split(/\s+/).filter(Boolean);return detailRows.filter((r:any)=>words.every(word=>normalName(r.name+' '+r.nni).includes(word)));},[detailRows,nameQuery]);
 const rate=(v:number|null)=>v===null?'Non disponible':new Intl.NumberFormat('fr-FR',{minimumFractionDigits:2,maximumFractionDigits:2}).format(v)+' €/h';
 const money=(cents:number)=>new Intl.NumberFormat('fr-FR',{style:'currency',currency:'EUR',maximumFractionDigits:0}).format(cents/100);
 const groupTable=(title:string,rows:any[])=> <section className="panel"><div className="panel-heading"><h2>{title}</h2><button className="btn" onClick={()=>csv('masse-salariale-'+title+'.csv',[['Groupe','Agents','Agents calculés','Agents exclus','Brut mensuel estimé hors primes EUR','Brut annualisé estimé hors primes EUR','Primes annuelles RPC RPEM estimées EUR','Brut annualisé avec primes estimé EUR','Primes inconnues agents','Mois','Grille','Majoration résidentielle','Référence grille','Référence primes'],...rows.map(r=>[colleges[r.label]||r.label,r.agents,r.covered,r.excluded,r.monthlyCents/100,r.monthlyCents*months/100,r.annualBonusCents/100,(r.monthlyCents*months+r.annualBonusCents)/100,r.bonusUnknown,months,data.gridDate,'AMT Centre 24 % ; autres agences 24,5 %',data.gridId,data.bonusId])])}><Download size={15}/>Exporter</button></div><div className="table-scroll"><table><thead><tr><th>Groupe</th><th>Agents</th><th>Calculés / exclus</th><th>Brut mensuel estimé hors primes</th><th>Brut annualisé estimé hors primes ({months} mois)</th><th>Primes annuelles RPC / RPEM</th><th>Brut annualisé avec primes</th></tr></thead><tbody>{rows.map(r=><tr key={r.label}><td>{colleges[r.label]||r.label}</td><td>{r.agents}</td><td>{r.covered} / {r.excluded}</td><td>{money(r.monthlyCents)}</td><td>{money(r.monthlyCents*months)}</td><td>{money(r.annualBonusCents)}</td><td>{money(r.monthlyCents*months+r.annualBonusCents)}{r.bonusUnknown>0&&<small>{r.bonusUnknown} prime(s) inconnue(s)</small>}</td></tr>)}</tbody></table></div></section>;
 return <><section className="panel"><div className="panel-heading"><div><div className="eyebrow">PROJECTION STATUTAIRE · RÉFÉRENCES VALIDÉES</div><h2>Masse salariale annuelle estimée · hors et avec primes</h2><p>Effectifs, NR et anciennetés au {date(data.referenceDate)}, valorisés avec la grille du {date(data.gridDate)}.</p></div></div><div className="analysis-options"><label>Grille IEG / SNB<select value={data.gridId} onChange={e=>{const g=data.references.find((r:any)=>r.id===e.target.value);setGridRef(e.target.value);if(residence!=='agency'&&!g.residences.includes(residence))setResidence(g.residences[0]);}}>{data.references?.filter((r:any)=>r.kind==='grid').map((r:any)=><option value={r.id} key={r.id}>{r.date} · {r.name}</option>)}</select></label><label>Primes annuelles<select value={data.bonusId} onChange={e=>setBonusRef(e.target.value)}>{data.references?.filter((r:any)=>r.kind==='bonuses').map((r:any)=><option value={r.id} key={r.id}>{r.date.slice(0,4)} · {r.name}</option>)}</select></label><span className="filter-note">Majoration résidentielle automatique : AMT Centre 24 % · AMT Est et Sud-Ouest 24,5 % · autres agences 24,5 % provisoirement.</span><label>Annualisation<select value={months} onChange={e=>setMonths(Number(e.target.value))}><option value={13}>13 mois · hypothèse d’un mois supplémentaire</option><option value={12}>12 mois · salaire mensuel uniquement</option></select></label></div><div className="notice"><AlertCircle size={16}/><span>Estimation à temps plein et à effectif, NR et échelon constants sur toute l’année. Le montant avec primes ajoute uniquement les moyennes annuelles RPC / RPEM {data.bonusReferenceYear} par GF. JDD, PVPA, autres primes, heures supplémentaires, indemnités et cotisations patronales restent exclus. Ce montant n’est pas la masse salariale réellement versée.</span></div></section><div className="kpi-grid"><Metric title={'Brut annualisé hors primes · '+months+' mois'} value={money(data.monthlyCents*months)}/><Metric title={'Brut annualisé avec primes · '+months+' mois'} value={money(data.monthlyCents*months+data.annualBonusCents)}/><Metric title="Agents calculés / population" value={data.covered+' / '+data.total}/><Metric title="Primes annuelles RPC / RPEM estimées" value={money(data.annualBonusCents)}/></div><section className="panel prose"><h2>Hypothèses et couverture</h2><p>Barèmes historiques intégrés : 2013 à 2025, avec les changements de juillet 2018 et juillet 2022. Les grilles complètes de 2009 à 2012 restent à fournir ; aucune grille n’est extrapolée pour ces années. Le choix de grille valorise toute la photographie au barème sélectionné, sans reconstituer les changements de tarif en cours d’année.</p>{data.references?.find((r:any)=>r.id===data.gridId)?.note&&<p>{data.references.find((r:any)=>r.id===data.gridId).note}</p>}<p>Primes retenues : colonne « TOTAL DISPOSITIFS – Montant moyen » de la référence {data.bonusReferenceYear} (RPC / RPEM). JDD et PVPA ne sont pas pris en compte. La moyenne annuelle de chaque GF est appliquée à chaque agent calculable de ce GF, puis ajoutée une seule fois au brut annualisé, sur 12 comme sur 13 mois.</p><p>Les populations éligibles du tableau des primes peuvent différer des effectifs de la photographie sélectionnée. Faute d’éligibilité individuelle, l’application de la moyenne à tous les agents du GF est une extrapolation et ne reconstitue pas les primes réellement versées. Les primes de la référence sélectionnée sont utilisées comme référence constante pour toutes les photographies.</p><p>{data.bonusUnknown} agents calculés ont un GF sans moyenne de prime disponible : leur prime reste non chiffrée et le total avec primes est incomplet si ce nombre est supérieur à zéro. Une moyenne égale à zéro (GF 2) est distinguée d’une donnée inconnue.</p><p>{data.anchored} agents ont une ancienneté calculée depuis une ancienneté publiée ou une date d’entrée connue. Pour {data.firstSeenEstimates} agents, la première apparition dans les fichiers est supposée être l’entrée en carrière : une carrière commencée avant cette date peut conduire à sous-estimer le salaire. Tous les échelons sont déduits de l’ancienneté, sans vérification d’un échelon individuel de paie.</p><p>{data.excluded} agents exclus du total faute de NNI rapproché, de NR dans la grille ou d’ancienneté calculable. {data.manualPresence} présences confirmées manuellement incluses. Les effectifs calculés sont distincts par identité, sans double comptage des lignes.</p><details><summary>Calcul et seuils d’échelon</summary><p>Pour chaque agent : salaire mensuel de la grille au NR et à l’échelon estimé × {months}. La quotité de travail est supposée égale à 100 % ; la majoration résidentielle est appliquée selon l’agence : AMT Centre 24 %, AMT Est et AMT Sud-Ouest 24,5 %, autres agences 24,5 % provisoirement. Si le barème requis manque dans la grille, l’agent est exclu du calcul salarial sans substitution de taux. Les échelons n’évoluent pas pendant l’année projetée ; les entrées, sorties et changements de NR pendant l’année ne sont pas reconstitués.</p><p>Échelon 4 avant 6 ans ; 5 à 6 ans ; 6 à 9,5 ans ; 7 à 13 ans ; 8 à 17 ans ; 9 à 21 ans ; 10 à 25 ans ; 11 à 30 ans ; 12 à 34 ans. Les seuils sont ceux du document fourni, validés par le propriétaire. L’ancienneté de carrière calculée est utilisée comme approximation de l’ancienneté ouvrant droit à l’échelon.</p><p>Les situations historiques sont également valorisées aux tarifs de la grille sélectionnée : elles ne représentent pas les salaires de leur année d’origine. Un NR absent de la grille reste exclu, sans conversion ni interpolation.</p></details><details><summary>Moyennes annuelles de primes par GF</summary><div className="table-scroll"><table><thead><tr><th>GF</th><th>RPC / RPEM annuelle moyenne {data.bonusReferenceYear}</th></tr></thead><tbody>{Object.entries(data.bonusByGF).sort(([a],[b])=>Number(b)-Number(a)).map(([gf,cents])=><tr key={gf}><td>{gf}</td><td>{money(cents as number)}</td></tr>)}</tbody></table></div><a href={data.bonusId==='bonuses-2025'?'/sources/primes-2025.png':'/api/payroll/files/'+data.bonusId} target="_blank" rel="noreferrer" className="text-btn">Consulter le tableau de primes fourni</a></details><p><a className="text-btn" href={data.references?.find((r:any)=>r.id===data.gridId)?.sourceUrl||(data.gridId==='grid-2026'?'/sources/grille-salaire-2026.pdf':'/api/payroll/files/'+data.gridId)} target="_blank" rel="noreferrer">Consulter la grille de salaire sélectionnée</a> · <a className="text-btn" href="/sources/echelons-anciennete.pdf" target="_blank" rel="noreferrer">Consulter les seuils d’échelon</a></p></section>{groupTable('Par collège',data.colleges)}{groupTable('Par agence',data.agencies)}<section className="panel"><div className="panel-heading"><h2>Détail individuel du calcul</h2><button className="btn" onClick={()=>csv('masse-salariale-detail.csv',[['NNI','Nom','Collège','Agence','GF','NR','Ancienneté estimée','Échelon estimé','Méthode ancienneté','Première apparition supposée entrée','Présence manuelle','Brut mensuel hors primes EUR','Brut annualisé hors primes EUR','Prime annuelle moyenne RPC RPEM EUR','Brut annualisé avec primes EUR','Prime connue','Motif exclusion','Mois','Date situation','Date grille','Majoration résidentielle','Quotité supposée','Référence grille','Référence primes','Base horaire annuelle de paie','Taux horaire brut estimé hors primes EUR','Taux horaire brut estimé avec primes EUR'],...detailRows.map((r:any)=>[r.nni,r.name,colleges[r.college]||r.college,r.agency,r.gf,r.nr,r.years,r.level,r.method,r.firstSeenEstimate?'Oui':'Non',r.manualPresence?'Oui':'Non',r.monthlyCents===null?'':r.monthlyCents/100,r.monthlyCents===null?'':r.monthlyCents*months/100,r.annualBonusCents===null?'':r.annualBonusCents/100,r.monthlyCents===null?'':(r.monthlyCents*months+(r.annualBonusCents??0))/100,r.annualBonusCents===null?'Non':'Oui',r.reason,months,data.referenceDate,data.gridDate,r.residence,'100 %',data.gridId,data.bonusId,ANNUAL_HOURS,r.hourly.withoutBonuses,r.hourly.withBonuses])])}><Download size={15}/>Exporter tous les agents</button></div><button className="text-btn" aria-expanded={details} onClick={()=>setDetails(!details)}>{details?'Masquer les agents':'Afficher tous les agents ('+detailRows.length+')'}</button><div className="analysis-options"><label className="search-label"><Search size={16}/><input aria-label="Rechercher dans le détail des rémunérations" placeholder="Nom, prénom ou NNI" value={nameQuery} onChange={e=>{setNameQuery(e.target.value);setDetails(true);}}/></label>{nameQuery&&<button className="text-btn" onClick={()=>setNameQuery('')}>Effacer</button>}<span role="status">{filteredRows.length} / {detailRows.length} agents</span></div><p>Ordre alphabétique · Taux horaire hors primes : brut mensuel ÷ 151,6667 h, sans 13ᵉ mois. Équivalent avec primes : primes annuelles lissées sur 12 mois.</p>{details&&<div className="table-scroll"><table><thead><tr><th>Agent</th><th>NR</th><th>Majoration résidentielle</th><th>Ancienneté / échelon estimés</th><th>Brut annualisé hors primes</th><th>Prime annuelle RPC / RPEM</th><th>Brut annualisé avec primes</th><th>Taux horaire hors primes · €/h</th><th>Équivalent horaire avec primes · €/h</th><th>Méthode / exclusion</th></tr></thead><tbody>{filteredRows.map((r:any)=><tr key={r.agentId}><td><button className="text-btn" onClick={()=>onOpen(r.agentId)}>{r.name}</button><small>{r.nni}</small></td><td>{fmt(r.nr)}</td><td>{fmt((Number(r.residence)-1)*100)} %{r.residenceProvisional&&<small>Provisoire</small>}</td><td>{fmt(r.years)} ans · éch. {fmt(r.level)}</td><td>{r.monthlyCents===null?'Exclu':money(r.monthlyCents*months)}</td><td>{r.annualBonusCents===null?'Inconnue':money(r.annualBonusCents)}</td><td>{r.monthlyCents===null?'Exclu':money(r.monthlyCents*months+(r.annualBonusCents??0))}</td><td>{rate(r.hourly.withoutBonuses)}</td><td>{rate(r.hourly.withBonuses)}</td><td>{r.reason||r.method}</td></tr>)}{!filteredRows.length&&<tr><td colSpan={10}>Aucun agent ne correspond à cette recherche.</td></tr>}</tbody></table></div>}</section></>;
}

function HourlyIndividual({data}:{data:any}){
 const [query,setQuery]=useState('');
 const normalized=normalName(query);
 const rows=useMemo(()=>normalized.length>=2?[...data.rows].filter((r:any)=>normalName(String(r.name||'')+' '+String(r.nni||'')).includes(normalized)).sort((a:any,b:any)=>String(a.name||'').localeCompare(String(b.name||''),'fr',{sensitivity:'base'})):[],[data.rows,normalized]);
 return <section className="panel"><div className="panel-heading"><div><h2>Tarifs horaires individuels</h2><p>Rechercher un agent par nom, prénom ou NNI. La liste n'est pas affichée par défaut.</p></div></div>
 <div className="analysis-options"><label className="search-label"><Search size={16}/><input aria-label="Rechercher un tarif horaire individuel" placeholder="Nom, prénom ou NNI (2 caractères minimum)" value={query} onChange={e=>setQuery(e.target.value)}/></label>{query&&<button className="text-btn" onClick={()=>setQuery('')}>Effacer</button>}<span role="status">{normalized.length<2?'Saisir au moins 2 caractères':rows.length+' agent(s) trouvé(s)'}</span></div>
 {normalized.length>=2&&(rows.length?<div className="table-scroll"><table><thead><tr><th>Agent</th><th>GF</th><th>NR</th><th>Hors primes · €/h</th><th>Avec primes · €/h</th></tr></thead><tbody>{rows.map((r:any)=>{const h=hourlyRates([r],13);return <tr key={r.agentId}><td>{r.name}</td><td>{fmt(r.gf)}</td><td>{fmt(r.nr)}</td><td>{h.withoutBonuses===null?'Non disponible':fmt(h.withoutBonuses)+' €/h'}</td><td>{h.withBonuses===null?'Non disponible':fmt(h.withBonuses)+' €/h'}</td></tr>;})}</tbody></table></div>:<p className="filter-note">Aucun agent ne correspond à cette recherche.</p>)}
 </section>;
}
